    fn index_at(&self, t: Ticks) -> Option<usize> {
        if self.pieces.is_empty() {
            return None;
        }
        let found = self.pieces.iter().position(|p| t < p.to());
        Some(found.unwrap_or(self.pieces.len() - 1))
