    /// S(t): source ticks read by clip time `t`, `t` clamped to
    /// `[0, duration]`.
    pub(crate) fn source_at(&self, t: Ticks) -> f64 {
        let t = t.clamp(0, self.duration);
        let Some(i) = self.index_at(t) else {
            return 0.0;
